package org.overengineer.bettacraft.genetics;

import java.util.List;

/** Pattern ids; each has a mask texture {@code textures/entity/betta/pattern_<id>.png} (generated by tools/assetgen). */
public final class BettaPatterns {
    public static final String NONE = "none";
    private static final List<String> IDS = List.of("butterfly", "marble", "dragon", "koi", "mask", "tipped", "fade", "grizzle", "bars");

    private BettaPatterns() {}

    /** All real patterns (without "none"). */
    public static List<String> ids() {
        return IDS;
    }

    public static boolean isKnown(String id) {
        return IDS.contains(id);
    }

    public static String translationKey(String id) {
        return "pattern.bettacraft." + id;
    }

    public static String shapeTranslationKey(String shape) {
        return "shape.bettacraft." + shape;
    }
}
